// Pure Bash adapter for the bounded Go-to-Go upgrade rehearsal.
//
// The returned subshell deliberately delegates identity, authority, fencing,
// drain, readiness, smoke, snapshot, and rollback decisions to the sourced
// release helpers and the caller's extracted deploy functions. The inner Bash
// process is intentional: release-helper.sh declares its initialization state
// readonly, so a child process is required when the parent already sourced it.

export function buildGoUpgradeCycle() {
  return [
    "(",
    "set -Eeuo pipefail",
    "umask 077",
    "for required in ROOT PROJECT UPGRADE_GO_COMPOSE UPGRADE_COMMIT UPGRADE_VERSION UPGRADE_SNAPSHOT UPGRADE_RECOVERY PREVIOUS_GO_SNAPSHOT PHASE_FILE; do",
    "  value=\"${!required:-}\"",
    "  [[ -n \"${value}\" && \"${value}\" != *$'\\n'* && \"${value}\" != *$'\\r'* && \"${value}\" != *$'\\t'* ]] || { printf '%s\\n' \"go_upgrade_${required,,}_missing_or_unsafe\" >&2; exit 1; }",
    "done",
    "[[ \"${PROJECT}\" =~ ^[a-z0-9][a-z0-9_-]{0,62}$ ]] || { printf '%s\\n' go_upgrade_project_invalid >&2; exit 1; }",
    "[[ \"${UPGRADE_COMMIT}\" =~ ^[0-9a-f]{40}$ ]] || { printf '%s\\n' go_upgrade_commit_invalid >&2; exit 1; }",
    "[[ \"${UPGRADE_VERSION}\" =~ ^[0-9]+\\.[0-9]+\\.[0-9]+$ ]] || { printf '%s\\n' go_upgrade_version_invalid >&2; exit 1; }",
    "[[ ! -L \"${UPGRADE_RECOVERY}\" && ! -L \"${UPGRADE_SNAPSHOT}\" && ! -L \"${PHASE_FILE}\" ]] || { printf '%s\\n' go_upgrade_artifact_symlink >&2; exit 1; }",
    "export ROOT PROJECT UPGRADE_GO_COMPOSE UPGRADE_COMMIT UPGRADE_VERSION UPGRADE_SNAPSHOT UPGRADE_RECOVERY PREVIOUS_GO_SNAPSHOT PHASE_FILE",
    "for required_function in verify_container_release start_release_service start_release_backend start_release_edge go_upgrade_rollback_compose; do",
    "  declare -F \"${required_function}\" >/dev/null 2>&1 || { printf '%s\\n' \"go_upgrade_${required_function}_missing\" >&2; exit 1; }",
    "  export -f \"${required_function}\"",
    "done",
    "exec bash --noprofile --norc -s <<'DUALLANE_GO_UPGRADE'",
    "set -Eeuo pipefail",
    "umask 077",
    "source \"${ROOT}/deploy/production/release-helper.sh\"",
    "release_load_profile go-full",
    "RELEASE_STOP_TIMEOUT=10; RELEASE_STOP_ATTEMPTS=15; RELEASE_HEALTH_ATTEMPTS=30",
    "[[ \"${RELEASE_PROFILE_NAME}\" == go-full ]] || { printf '%s\\n' go_upgrade_profile_invalid >&2; exit 1; }",
    "for required_function in release_private_new_artifact_path release_verify_schema_upgrade_compatibility verify_container_release start_release_service start_release_backend start_release_edge go_upgrade_rollback_compose; do",
    "  declare -F \"${required_function}\" >/dev/null 2>&1 || { printf '%s\\n' \"go_upgrade_${required_function}_missing\" >&2; exit 1; }",
    "done",
    "",
    "# Match deploy.sh's Compose selection without sourcing its top-level command flow.",
    "compose() {",
    "  local -a files=()",
    "  if [[ -n \"${RELEASE_GO_ACTIVATION_COMPOSE_FILE:-}\" ]]; then",
    "    files=(-f \"${RELEASE_GO_ACTIVATION_COMPOSE_FILE}\")",
    "  else",
    "    files=(-f \"${UPGRADE_GO_COMPOSE}\")",
    "    if [[ -n \"${RELEASE_GO_IMAGE_OVERRIDE_FILE:-}\" ]]; then",
    "      files+=(-f \"${RELEASE_GO_IMAGE_OVERRIDE_FILE}\")",
    "    fi",
    "  fi",
    "  docker compose --project-name \"${PROJECT}\" --profile rollback \"${files[@]}\" \"$@\"",
    "}",
    "",
    "export PROJECT_DIR=\"${ROOT}\"",
    "export COMPOSE_PROJECT_NAME=\"${PROJECT}\"",
    "current_commit=\"${UPGRADE_COMMIT}\"",
    "expected_app_version=\"${UPGRADE_VERSION}\"",
    "RELEASE_GO_UPGRADE=true",
    "RELEASE_PREVIOUS_RELEASE_SNAPSHOT=\"${PREVIOUS_GO_SNAPSHOT}\"",
    "RELEASE_SNAPSHOT_FILE=\"${UPGRADE_SNAPSHOT}\"",
    "RELEASE_RECOVERY_FILE=\"${UPGRADE_RECOVERY}\"",
    "phase() { printf 'upgrade_%s\\n' \"$1\" >>\"${PHASE_FILE}\"; }",
    "release_private_new_artifact_path \"${UPGRADE_SNAPSHOT}\" 'Go upgrade snapshot'",
    "release_private_new_artifact_path \"${UPGRADE_RECOVERY}\" 'Go upgrade recovery'",
    ": >\"${UPGRADE_RECOVERY}\"",
    "",
    "phase validate",
    "release_validate_resolved_compose",
    "release_pin_compose_project",
    "[[ \"${COMPOSE_PROJECT_NAME}\" == \"${PROJECT}\" ]] || { printf '%s\\n' go_upgrade_compose_project_mismatch >&2; exit 1; }",
    "",
    "phase snapshot",
    "release_snapshot_app_state \"${UPGRADE_SNAPSHOT}\"",
    "release_snapshot_validate_for_go_cutover",
    "",
    "phase pin",
    "release_verify_go_edge_images",
    "release_verify_go_image_identity",
    "",
    "phase freeze",
    "release_freeze_go_activation_compose",
    "release_verify_activation_authority",
    "",
    "phase schema_compatibility",
    "release_verify_schema_upgrade_compatibility",
    "",
    "phase migrate",
    "release_run_go_migration_and_verify",
    "",
    "# start_release_backend is the actual deploy.sh ordering: old-owner fence,",
    "# activation drain, then verified Workspace/worker starts.",
    "phase fence_drain_activate",
    "start_release_backend",
    "",
    "phase edge",
    "start_release_edge",
    "",
    "phase smoke",
    "release_run_gateway_smoke go-full \"${UPGRADE_VERSION}\" \"${UPGRADE_COMMIT}\"",
    "",
    "phase capture",
    "release_capture_successful_go_snapshot",
    "",
    "phase rollback",
    "release_rollback_application",
    "phase complete",
    "DUALLANE_GO_UPGRADE",
    ")",
  ].join("\n");
}
